-- RCO-19 阶段 3 评审 DML，未执行；新增入口保持 DISABLED，角色写权限保持 REVOKED。
-- 本文件只能在 mor_platform 内执行；先按 README 核对每个业务编码唯一、ID/Route 无冲突。
-- 使用 SQL 标量子查询：重复编码会失败；缺失值由 NOT NULL 写入失败。客户端不得使用 --force。
START TRANSACTION;
SET @rco19_time=UTC_TIMESTAMP(6);
SET @rco19_admin=(SELECT role_id FROM t_role WHERE role_code='PLATFORM_ADMIN' AND scope_key='PLATFORM' AND status='ACTIVE');
SET @rco19_read=(SELECT permission_id FROM t_permission WHERE permission_code='RISK_DECISION_CONFIG_READ' AND status='ACTIVE');
SET @rco19_parent=(SELECT resource_id FROM t_console_resource WHERE resource_code='OPERATIONS_RISK_MANAGEMENT' AND channel='OPERATIONS' AND status='ACTIVE');
SET @rco19_target=(SELECT target_id FROM t_gateway_target WHERE target_service_code='operations-console-bff' AND channel='OPERATIONS' AND status='ACTIVE');







UPDATE t_role SET version=version+1,update_time=@rco19_time WHERE role_id=@rco19_admin;
COMMIT;
